import {pickHumanMove} from './ranks.js';
/** Persistent neural Go worker. Uses real KataGo weights and PUCT/MCTS locally. */
import {play} from './engine.js';
let worker=null,initializedModel=null,nextId=1,active=null;
export const STRONG_PRESETS={4:{visits:32,maxTimeMs:2200,model:'katago-b6.bin.gz'},5:{visits:96,maxTimeMs:5500,model:'katago-b6.bin.gz'},6:{visits:256,maxTimeMs:12000,model:'katago-b10.bin.gz'}};
const colorName=c=>c===1?'black':'white';
function boardRows(flat,size){return Array.from({length:size},(_,y)=>flat.slice(y*size,(y+1)*size).map(c=>c?colorName(c):null))}
function previousBoards(state){let flat=state.board.slice(),out=[];for(let k=state.moves.length-1;k>=Math.max(0,state.moves.length-2);k--){const m=state.moves[k];if(m.index>=0){flat[m.index]=0;for(const p of m.captured||[])flat[p]=3-m.color}out.push(boardRows(flat,state.size))}return out}
function repetitionKey(key,size){let packed='b|'+size+':';for(let i=0;i<key.length;i+=3)packed+=String.fromCharCode(65+(+key[i])*9+(+(key[i+1]||0))*3+(+(key[i+2]||0)));return packed}
/** Exported for exact same protocol in the Node inference tests. */
export function neuralRequest(state,{level=6,komi=6.5,visits,maxTimeMs,id=1,modelUrl}={}){const preset=STRONG_PRESETS[level]||STRONG_PRESETS[6],[previousBoard,previousPreviousBoard]=previousBoards(state);return {type:'katago:analyze',id,analysisGroup:'interactive',positionId:state.history.at(-1)+'-'+state.moves.length,positionKey:state.history.at(-1),modelUrl:modelUrl||new URL('./neural/'+preset.model,import.meta.url).href,backend:'wasm',board:boardRows(state.board,state.size),previousBoard,previousPreviousBoard,currentPlayer:colorName(state.toPlay),moveHistory:state.moves.slice(-5).map(m=>({x:m.index<0?-1:m.index%state.size,y:m.index<0?-1:Math.floor(m.index/state.size),player:colorName(m.color)})),repetitionHistory:state.history.map(key=>repetitionKey(key,state.size)),komi,rules:'chinese',topK:50,analysisPvLen:5,visits:visits??preset.visits,maxTimeMs:maxTimeMs??preset.maxTimeMs,batchSize:1,maxChildren:64,wideRootNoise:0,rootPolicyTemperature:1,nnRandomize:false,conservativePass:true,ownershipMode:'none',reuseTree:true,reportDuringSearchEveryMs:400}}
export function pickNeuralMove(state,analysis){for(const m of analysis.moves||[]){const index=m.x<0||m.y<0?-1:m.y*state.size+m.x;if(play(state,index).ok)return index}throw new Error('신경망 엔진이 합법적인 수를 찾지 못했습니다. 다시 시도해 주세요.')}
function rejectActive(error){if(active){const a=active;active=null;clearTimeout(a.timer);a.detach?.();a.reject(error)}}
export function cancelStrongSearch(){worker?.terminate();worker=null;initializedModel=null;rejectActive(new DOMException('계산을 취소했습니다.','AbortError'))}
function ensureWorker(){if(worker)return worker;worker=new Worker(new URL('./neural/worker.js',import.meta.url),{type:'module'});worker.onerror=e=>{const message=e.message||'신경망 엔진을 불러오지 못했습니다.';worker?.terminate();worker=null;initializedModel=null;rejectActive(new Error(message))};worker.onmessageerror=()=>{worker?.terminate();worker=null;initializedModel=null;rejectActive(new Error('신경망 응답을 읽지 못했습니다.'))};worker.onmessage=({data:m})=>{const a=active;if(!a)return;if(m.type==='katago:notice'){a.notice=m.message;return}if(m.type==='katago:init_result'){if(!m.ok){initializedModel=null;rejectActive(new Error(m.error||'신경망 준비 실패'));return}initializedModel=a.request.modelUrl;a.backend=m.backend;a.modelName=m.modelName;a.progress?.({phase:'ready',backend:m.backend,modelName:m.modelName});a.progress?.({phase:'searching',visits:0,backend:m.backend});worker.postMessage(a.request);return}if(m.id!==a.request.id)return;if(m.type==='katago:analyze_update'&&m.ok){a.progress?.({phase:'searching',visits:m.analysis.rootVisits,backend:m.backend,modelName:m.modelName});return}if(m.type==='katago:analyze_result'){if(!m.ok){rejectActive(new Error(m.error||'신경망 분석 실패'));return}try{if(a.rank&&m.humanPolicyError)throw new Error(m.humanPolicyError);const index=a.rank?pickHumanMove(a.state,m.analysis,i=>play(a.state,i).ok):pickNeuralMove(a.state,m.analysis),value={index,visits:m.analysis.rootVisits,elapsedMs:Math.round(performance.now()-a.started),backend:m.backend,modelName:m.modelName,analysis:m.analysis};active=null;clearTimeout(a.timer);a.detach?.();a.resolve(value)}catch(error){rejectActive(error)}}};return worker}
export async function chooseStrongMove(state,{level=6,komi=6.5,onProgress,signal,visits,maxTimeMs,rank}={}){if(state.finished)throw new Error('이미 끝난 대국입니다.');if(signal?.aborted)throw new DOMException('계산을 취소했습니다.','AbortError');if(active)cancelStrongSearch();const w=ensureWorker(),request=neuralRequest(state,{level,komi,visits,maxTimeMs,id:nextId++});if(rank){request.humanModelUrl=new URL('./neural/human-model.json',import.meta.url).href;request.humanSlProfile='rank_'+rank;request.visits=24;request.maxTimeMs=2200;request.reuseTree=false;}return new Promise((resolve,reject)=>{const started=performance.now(),progress=typeof onProgress==='function'?onProgress:null;const timer=setTimeout(()=>{if(active?.request.id===request.id){w.terminate();worker=null;initializedModel=null;rejectActive(new Error('신경망 계산이 오래 걸립니다. 다시 시도하거나 한 단계 낮춰 주세요.'))}},300000);const abort=()=>{if(active?.request.id===request.id)cancelStrongSearch()};signal?.addEventListener('abort',abort,{once:true});active={state,request,rank,resolve,reject,progress,started,timer,detach:()=>signal?.removeEventListener('abort',abort)};if(initializedModel===request.modelUrl){progress?.({phase:'searching',visits:0});w.postMessage(request)}else{progress?.({phase:'loading'});w.postMessage({type:'katago:init',modelUrl:request.modelUrl,backend:'wasm'})}})}

export async function analyzeStrongPosition(state,options={}){return (await chooseStrongMove({...state,finished:false},{level:6,...options})).analysis}
